// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {Authority, Authorized} from "./Authority.sol";
import {LiquidityVault} from "./LiquidityVault.sol";
import {RiskMath} from "../libraries/RiskMath.sol";
import {Types} from "../libraries/Types.sol";

/// @title FinancingEngine
/// @notice Debt, interest and the rate model for one settlement market.
///
/// @dev Debt is denominated in **USD**, not in settlement-token units. Borrowing $1,000 creates
///      $1,000 of debt regardless of what the stablecoin does afterwards; the token amount moved
///      is derived from the oracle at the moment of transfer. If the settlement asset depegs, the
///      borrower owes the same dollars and a different number of tokens, which is the
///      economically correct answer and the one that keeps the collateral maths coherent.
///
///      Principal is carried scaled against a monotone index (spec/accounting.md §3.1). The index
///      steps on every interaction, so there is no keeper whose absence quietly stops interest.
contract FinancingEngine is Authorized {
    struct RateParams {
        uint16 baseBps;
        uint16 slope1Bps;
        uint16 slope2Bps;
        uint16 kinkBps;
        uint16 reserveFactorBps;
    }

    LiquidityVault public immutable vault;

    uint256 public borrowIndex = Types.WAD;
    uint64 public lastAccrualAt;
    uint256 public totalScaledPrincipal;

    RateParams public rate;
    address public clearingHouse;

    mapping(address account => uint256) public scaledPrincipalOf;

    event Accrued(uint256 index, uint256 rateBps, uint256 interestDelta);
    event Borrowed(address indexed account, uint256 amountUsd18, uint256 scaledDelta);
    event Repaid(address indexed account, uint256 amountUsd18, uint256 scaledDelta);
    event RateParamsSet(RateParams params);
    event ClearingHouseSet(address clearingHouse);

    error OnlyClearingHouse();
    error ClearingHouseAlreadySet();
    error BadRateParams();

    modifier onlyClearingHouse() {
        if (msg.sender != clearingHouse) revert OnlyClearingHouse();
        _;
    }

    constructor(Authority authority_, LiquidityVault vault_, RateParams memory rate_) Authorized(authority_) {
        vault = vault_;
        _setRate(rate_);
        lastAccrualAt = uint64(block.timestamp);
    }

    function setClearingHouse(address ch) external onlyRole(authority.GOVERNANCE()) {
        if (clearingHouse != address(0)) revert ClearingHouseAlreadySet();
        clearingHouse = ch;
        emit ClearingHouseSet(ch);
    }

    function setRateParams(RateParams calldata r) external onlyRole(authority.GOVERNANCE()) {
        accrue();
        _setRate(r);
    }

    /// @notice Accrue and hand the interest delta back to the caller for unit conversion.
    /// @dev Only ClearingHouse may call this, because only ClearingHouse can price the delta.
    function accrueFor() external onlyClearingHouse returns (uint256 interestDeltaUsd18) {
        (, interestDeltaUsd18) = accrue();
    }

    function _setRate(RateParams memory r) internal {
        if (r.kinkBps == 0 || r.kinkBps >= Types.BPS || r.reserveFactorBps > Types.BPS) {
            revert BadRateParams();
        }
        rate = r;
        emit RateParamsSet(r);
    }

    // ---------------------------------------------------------------------------------
    // Interest
    // ---------------------------------------------------------------------------------

    /// @notice Borrows as of the last accrual, using the stored index.
    /// @dev Utilisation is measured from settled state. Deriving the rate from the *projected*
    ///      index would make `currentIndex` and `currentRateBps` mutually recursive, and the
    ///      economics agree with the mechanics: a rate applies over the interval that starts
    ///      where the last one stopped.
    function totalBorrowsStored() public view returns (uint256) {
        return RiskMath.mulDivUp(totalScaledPrincipal, borrowIndex, Types.WAD);
    }

    function currentRateBps() public view returns (uint256) {
        return RiskMath.borrowRateBps(
            vault.availableCash(),
            totalBorrowsStored(),
            rate.baseBps,
            rate.slope1Bps,
            rate.slope2Bps,
            rate.kinkBps
        );
    }

    /// @notice The index as it would be right now, without writing.
    /// @dev Every view that reports debt uses this rather than the stored index, so a quote is
    ///      never cheaper than the transaction that follows it.
    function currentIndex() public view returns (uint256) {
        uint256 dt = block.timestamp - lastAccrualAt;
        if (dt == 0) return borrowIndex;
        return RiskMath.accrueIndex(borrowIndex, currentRateBps(), dt);
    }

    /// @notice Advance the index and report the interest recognised, in USD.
    /// @return index the new borrow index
    /// @return interestDeltaUsd18 interest recognised since the last accrual
    ///
    /// @dev This engine deliberately does NOT write to the liquidity vault. Debt here is
    ///      denominated in USD; the vault's books are denominated in settlement-token units. The
    ///      engine has no oracle and therefore cannot convert between them, and the version of
    ///      this function that pushed a usd18 delta straight into `LiquidityVault.accrue`
    ///      inflated vault NAV by roughly 271,000,000x and locked every lender out of their own
    ///      deposit. Conversion belongs at the one boundary that holds a price: ClearingHouse.
    function accrue() public returns (uint256 index, uint256 interestDeltaUsd18) {
        uint256 dt = block.timestamp - lastAccrualAt;
        if (dt == 0) return (borrowIndex, 0);

        uint256 rBps = currentRateBps();
        uint256 before = totalBorrowsStored();
        borrowIndex = RiskMath.accrueIndex(borrowIndex, rBps, dt);
        lastAccrualAt = uint64(block.timestamp);

        interestDeltaUsd18 = totalBorrowsStored() - before;

        emit Accrued(borrowIndex, rBps, interestDeltaUsd18);
        return (borrowIndex, interestDeltaUsd18);
    }

    function totalBorrowsUsd18() public view returns (uint256) {
        return RiskMath.mulDivUp(totalScaledPrincipal, currentIndex(), Types.WAD);
    }

    /// @notice Debt owed by `account`, in USD, rounded up.
    function debtOf(address account) public view returns (uint256) {
        return RiskMath.mulDivUp(scaledPrincipalOf[account], currentIndex(), Types.WAD);
    }

    // ---------------------------------------------------------------------------------
    // ClearingHouse-driven mutation
    // ---------------------------------------------------------------------------------

    function onBorrow(address account, uint256 amountUsd18) external onlyClearingHouse {
        accrue();
        uint256 scaledDelta = RiskMath.mulDivUp(amountUsd18, Types.WAD, borrowIndex);
        scaledPrincipalOf[account] += scaledDelta;
        totalScaledPrincipal += scaledDelta;
        emit Borrowed(account, amountUsd18, scaledDelta);
    }

    /// @notice Apply a repayment.
    /// @return appliedUsd18 the portion of `amountUsd18` that actually reduced debt
    /// @dev Overpayment is capped at the outstanding debt and reported back, so the caller
    ///      refunds the difference rather than the protocol quietly keeping it. Invariant I-04:
    ///      the reduction is computed from the caller's amount exactly once, and a replay finds
    ///      nothing left to reduce.
    function onRepay(address account, uint256 amountUsd18, bool repayAll)
        external
        onlyClearingHouse
        returns (uint256 appliedUsd18)
    {
        accrue();

        uint256 scaled = scaledPrincipalOf[account];
        if (scaled == 0) return 0;

        uint256 outstanding = RiskMath.mulDivUp(scaled, borrowIndex, Types.WAD);

        if (repayAll || amountUsd18 >= outstanding) {
            // Explicit full-clear path. Relying on rounding to land exactly on zero is how dust
            // debt survives a "repay all" and an account can never be closed.
            scaledPrincipalOf[account] = 0;
            totalScaledPrincipal -= scaled;
            emit Repaid(account, outstanding, scaled);
            return outstanding;
        }

        uint256 scaledDelta = RiskMath.mulDiv(amountUsd18, Types.WAD, borrowIndex);
        if (scaledDelta > scaled) scaledDelta = scaled;
        scaledPrincipalOf[account] = scaled - scaledDelta;
        totalScaledPrincipal -= scaledDelta;

        appliedUsd18 = amountUsd18;
        emit Repaid(account, appliedUsd18, scaledDelta);
    }

    /// @notice Retire an unrecoverable position and report the loss in USD.
    /// @dev Reports rather than writes, for the same unit-boundary reason as `accrue`. The caller
    ///      converts to token units before touching the vault's books.
    function writeOff(address account) external onlyClearingHouse returns (uint256 lossUsd18) {
        accrue();
        uint256 scaled = scaledPrincipalOf[account];
        if (scaled == 0) return 0;
        lossUsd18 = RiskMath.mulDivUp(scaled, borrowIndex, Types.WAD);
        scaledPrincipalOf[account] = 0;
        totalScaledPrincipal -= scaled;
    }
}

src/core/FeeController.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {Authority, Authorized} from "./Authority.sol";
import {RiskPolicyRegistry} from "./RiskPolicyRegistry.sol";
import {Types} from "../libraries/Types.sol";

/// @title FeeController
/// @notice Every protocol economic parameter, in one place, with bounds.
/// @dev Fee constants scattered through contracts are fee constants nobody can audit as a set. The
///      question an auditor actually asks is "what is the most this protocol can take from me", and
///      answering it should not require reading five contracts.
///
///      Three rules run through the file.
///
///      **Every parameter has a hard ceiling written in the bytecode.** Not a governance-settable
///      ceiling — a constant. Governance that can raise its own limit has no limit, and the whole
///      point of bounding a liquidation fee is that the party who benefits from raising it is the
///      party who would be setting it.
///
///      **Increases and decreases are not the same action.** Lowering what the protocol charges
///      cannot harm a user, so it applies immediately. Raising it changes the economics an
///      outstanding quote was produced under, so it advances the risk epoch and that quote is
///      refused rather than executed under terms nobody showed the user.
///
///      **Parameters exist for products that exist.** The interfaces for trading and repo fees are
///      declared so their shape is fixed, and they are inert: setting either to anything but zero
///      reverts until there is a venue to charge for. A fee schedule for a product nobody can use is
///      a revenue claim, not an interface.
contract FeeController is Authorized {
    RiskPolicyRegistry public immutable policies;

    // ---------------------------------------------------------------------------------
    // Ceilings. Constant, not settable.
    // ---------------------------------------------------------------------------------

    /// @dev Above roughly this, liquidating becomes more attractive than lending and keepers start
    ///      preferring accounts near the boundary. It also bounds how much of a breached position a
    ///      keeper can extract in a single round.
    uint16 public constant MAX_LIQUIDATOR_INCENTIVE_BPS = 1_000; // 10%

    /// @dev The protocol's cut of a liquidation. Deliberately an order of magnitude below the
    ///      keeper's: the protocol is not the party taking execution risk, and a protocol earning
    ///      more from a liquidation than the keeper who performed it has an incentive nobody should
    ///      want it to have.
    uint16 public constant MAX_PROTOCOL_LIQUIDATION_FEE_BPS = 100; // 1%

    /// @dev Charged once on a draw. Bounded low because it is the one fee a borrower cannot avoid
    ///      by behaving well.
    uint16 public constant MAX_ORIGINATION_FEE_BPS = 50; // 0.5%

    /// @dev The protocol's share of borrower interest. The rest is lender yield.
    uint16 public constant MAX_FINANCING_RESERVE_FACTOR_BPS = 3_000; // 30%

    /// @dev A liquidation must never consume more than the position. Incentive plus fee is checked
    ///      jointly, because two individually-bounded parameters can still be ruinous together.
    uint16 public constant MAX_COMBINED_LIQUIDATION_TAKE_BPS = 1_050; // 10.5%

    // ---------------------------------------------------------------------------------
    // Parameters
    // ---------------------------------------------------------------------------------

    /// @notice Paid to whoever performs a liquidation, out of the proceeds.
    uint16 public liquidatorIncentiveBps;
    /// @notice The protocol's cut of a liquidation, out of the same proceeds.
    uint16 public protocolLiquidationFeeBps;
    /// @notice Charged on a new draw.
    uint16 public originationFeeBps;
    /// @notice The protocol's share of borrower interest; the remainder accrues to lenders.
    uint16 public financingReserveFactorBps;

    /// @notice Declared so the shape is fixed. Inert until there is a venue to charge for.
    uint16 public tradingFeeBps;
    /// @notice Declared so the shape is fixed. Inert until securities lending exists.
    uint16 public repoFeeBps;

    /// @notice Where protocol fees accrue.
    address public treasury;

    event FeeSet(bytes32 indexed parameter, uint256 previous, uint256 current, bool increased);
    event TreasurySet(address previous, address current);

    error AboveCeiling(bytes32 parameter, uint256 requested, uint256 ceiling);
    error CombinedLiquidationTakeTooHigh(uint256 requested, uint256 ceiling);
    error ProductNotLive(bytes32 parameter);
    error ZeroTreasury();

    constructor(Authority authority_, RiskPolicyRegistry policies_, address treasury_)
        Authorized(authority_)
    {
        if (treasury_ == address(0)) revert ZeroTreasury();
        policies = policies_;
        treasury = treasury_;

        // Defaults chosen so a fresh deployment has a working liquidation market rather than a
        // dormant one. A protocol whose keeper incentive starts at zero has no keepers on the day
        // it first needs them.
        liquidatorIncentiveBps = 500; // 5%
        protocolLiquidationFeeBps = 50; // 0.5%
        originationFeeBps = 0;
        financingReserveFactorBps = 1_000; // 10%
    }

    // ---------------------------------------------------------------------------------
    // Setters
    // ---------------------------------------------------------------------------------

    /// @dev Shared tail for every setter. Raising a fee changes the economics an outstanding quote
    ///      was produced under, so it moves the epoch and those quotes are refused. Lowering one
    ///      cannot harm anybody holding a quote, so it does not.
    function _record(bytes32 parameter, uint256 previous, uint256 current, bytes32 cause) private {
        bool increased = current > previous;
        emit FeeSet(parameter, previous, current, increased);
        if (increased) policies.bumpEpoch(cause);
    }

    function setLiquidatorIncentive(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps > MAX_LIQUIDATOR_INCENTIVE_BPS) {
            revert AboveCeiling("liquidatorIncentive", bps, MAX_LIQUIDATOR_INCENTIVE_BPS);
        }
        _requireCombinedTakeInBounds(bps, protocolLiquidationFeeBps);

        uint16 previous = liquidatorIncentiveBps;
        liquidatorIncentiveBps = bps;
        // Risk-relevant in principle in both directions, because it changes how much collateral a
        // liquidation consumes and therefore how much a round repairs. Only an increase can make an
        // outstanding quote worse than the user was shown.
        _record("liquidatorIncentive", previous, bps, keccak256("LIQUIDATOR_INCENTIVE_RAISED"));
    }

    function setProtocolLiquidationFee(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps > MAX_PROTOCOL_LIQUIDATION_FEE_BPS) {
            revert AboveCeiling("protocolLiquidationFee", bps, MAX_PROTOCOL_LIQUIDATION_FEE_BPS);
        }
        _requireCombinedTakeInBounds(liquidatorIncentiveBps, bps);

        uint16 previous = protocolLiquidationFeeBps;
        protocolLiquidationFeeBps = bps;
        _record("protocolLiquidationFee", previous, bps, keccak256("PROTOCOL_LIQUIDATION_FEE_RAISED"));
    }

    function setOriginationFee(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps > MAX_ORIGINATION_FEE_BPS) {
            revert AboveCeiling("originationFee", bps, MAX_ORIGINATION_FEE_BPS);
        }
        uint16 previous = originationFeeBps;
        originationFeeBps = bps;
        _record("originationFee", previous, bps, keccak256("ORIGINATION_FEE_RAISED"));
    }

    function setFinancingReserveFactor(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps > MAX_FINANCING_RESERVE_FACTOR_BPS) {
            revert AboveCeiling("financingReserveFactor", bps, MAX_FINANCING_RESERVE_FACTOR_BPS);
        }
        uint16 previous = financingReserveFactorBps;
        financingReserveFactorBps = bps;
        // Taking a larger share of interest reduces lender yield. It does not change a borrower's
        // risk, so it does not disturb the epoch.
        emit FeeSet("financingReserveFactor", previous, bps, bps > previous);
    }

    /// @dev Both accept zero and nothing else. The parameter exists so its shape is fixed and
    ///      callers can already read it; charging for a product that cannot be used would be a
    ///      revenue claim rather than an interface.
    function setTradingFee(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps != 0) revert ProductNotLive("tradingFee");
        tradingFeeBps = 0;
    }

    function setRepoFee(uint16 bps) external onlyRole(authority.GOVERNANCE()) {
        if (bps != 0) revert ProductNotLive("repoFee");
        repoFeeBps = 0;
    }

    function setTreasury(address treasury_) external onlyRole(authority.GOVERNANCE()) {
        if (treasury_ == address(0)) revert ZeroTreasury();
        address previous = treasury;
        treasury = treasury_;
        emit TreasurySet(previous, treasury_);
    }

    /// @dev Checked jointly. Two individually-bounded parameters can still be ruinous together, and
    ///      the number that matters to a borrower is what leaves their position in total.
    function _requireCombinedTakeInBounds(uint16 incentive, uint16 fee) private pure {
        uint256 combined = uint256(incentive) + fee;
        if (combined > MAX_COMBINED_LIQUIDATION_TAKE_BPS) {
            revert CombinedLiquidationTakeTooHigh(combined, MAX_COMBINED_LIQUIDATION_TAKE_BPS);
        }
    }

    // ---------------------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------------------

    /// @notice Total basis points of liquidation proceeds that do not retire debt.
    /// @dev The single number the planner needs. Collateral must be grossed up by this to retire a
    ///      given amount of debt, and every extra basis point here is a basis point of the
    ///      borrower's position that repairs nothing.
    function liquidationTakeBps() external view returns (uint16) {
        return liquidatorIncentiveBps + protocolLiquidationFeeBps;
    }

    /// @notice How proceeds split, in settlement-token units.
    /// @dev Returned as one call so a caller cannot compute two of the three and let rounding invent
    ///      the difference. `toDebt` is the residual by construction, which is what makes the split
    ///      exact rather than approximately exact — and it means any rounding dust lands on the
    ///      borrower's debt rather than in a fee.
    function splitLiquidationProceeds(uint256 proceeds)
        external
        view
        returns (uint256 toKeeper, uint256 toProtocol, uint256 toDebt)
    {
        toKeeper = (proceeds * liquidatorIncentiveBps) / Types.BPS;
        toProtocol = (proceeds * protocolLiquidationFeeBps) / Types.BPS;
        toDebt = proceeds - toKeeper - toProtocol;
    }
}

src/interfaces/IOracleAdapter.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

/// @notice The only shape the risk pipeline knows about a price source.
/// @dev Adapters translate. They never decide. An adapter returns what it observed and how
///      fresh it is; whether that is good enough to lend against is a policy question answered
///      by RiskMath against the asset's `maxOracleAge`.
interface IOracleAdapter {
    /// @return priceUsd18 price scaled to 18 decimals, or 0 if the source produced no valid price
    /// @return updatedAt  timestamp of the observation
    function getPrice(bytes32 assetId) external view returns (uint256 priceUsd18, uint64 updatedAt);

    /// @notice Whether the settlement layer itself is currently trustworthy.
    /// @dev On an L2 this is the sequencer uptime feed. A price nobody can arbitrage against is
    ///      not a price you may lend against, however recent its timestamp.
    function sequencerStatus() external view returns (bool up, uint64 lastRestartAt, uint64 gracePeriod);
}

/// @notice Minimal Chainlink aggregator surface.
interface IAggregatorV3 {
    function decimals() external view returns (uint8);
    function description() external view returns (string memory);
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

src/libraries/RiskMath.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {Types} from "./Types.sol";

/// @title RiskMath
/// @notice The deterministic valuation and capacity pipeline. This is the onchain authority
///         for every number Usance lends against.
/// @dev Pure. Reads no storage, no block state, no oracle. Everything it needs arrives in the
///      argument list, which is what lets `fixtures/canonical/risk-scenarios.json` drive it
///      directly and lets `crates/risk-core` be a genuine differential oracle rather than a
///      loose approximation.
///
///      Every line here maps to a numbered section of spec/accounting.md. If the two disagree,
///      the spec is right and this file is a bug.
library RiskMath {
    using Types for Types.AccountStatus;

    error ExitCurveEmpty();
    error AssetsNotOrdered();
    error ZeroDenominator();

    // ---------------------------------------------------------------------------------
    // §1.2 Rounding primitives
    // ---------------------------------------------------------------------------------

    /// @notice Round-down multiply-divide with a full 512-bit intermediate.
    /// @dev Solidity 0.8 reverts on overflow of `a * b`, which for realistic quantities times
    ///      1e18 prices is reachable. The 512-bit path is not an optimisation, it is the
    ///      difference between a correct valuation and a revert on a large position.
    function mulDiv(uint256 a, uint256 b, uint256 d) internal pure returns (uint256 result) {
        if (d == 0) revert ZeroDenominator();

        // Split a*b into 512 bits: prod1 * 2**256 + prod0
        uint256 prod0;
        uint256 prod1;
        unchecked {
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }

            if (prod1 == 0) {
                return prod0 / d;
            }

            // Result must fit in 256 bits.
            require(d > prod1, "RiskMath: mulDiv overflow");

            // Remainder-subtraction, then exact division by the odd part of d.
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = d & (0 - d);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;

            // XOR, not exponentiation. This is the standard Newton-Raphson seed for a modular
            // inverse: `(3 * d) ^ 2` is exact for `d` modulo 2**4, and each of the six doublings
            // below takes it to 8, 16, 32, 64, 128 and finally 256 bits. Slither flags it as a
            // likely `**` typo on every run, and "fixing" it to `**` silently returns wrong
            // products for any division that is not exact. The differential fixtures would catch
            // that — S23 through S28 exist because the 18-decimal ones all divided evenly — but
            // the note belongs here, where the tempting edit is.
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;

            result = prod0 * inv;
        }
    }

    /// @notice Round-up multiply-divide. Used for every quantity the user owes.
    function mulDivUp(uint256 a, uint256 b, uint256 d) internal pure returns (uint256) {
        if (a == 0 || b == 0) return 0;
        uint256 down = mulDiv(a, b, d);
        // mulmod detects a non-zero remainder without recomputing the 512-bit product.
        return mulmod(a, b, d) == 0 ? down : down + 1;
    }

    function max(Types.AccountStatus x, Types.AccountStatus y) internal pure returns (Types.AccountStatus) {
        return uint8(x) >= uint8(y) ? x : y;
    }

    // ---------------------------------------------------------------------------------
    // §4 Valuation
    // ---------------------------------------------------------------------------------

    /// @notice §4.3 — the recovery band for a position of this size.
    /// @dev First tier whose threshold is at or above the position; past the last threshold the
    ///      last (worst) tier applies. `RiskPolicyRegistry` guarantees the curve is ascending in
    ///      threshold and non-increasing in recovery, so "last" really is "worst".
    function selectRecoveryBps(Types.ExitTier[] memory curve, uint256 marketValue)
        internal
        pure
        returns (uint16)
    {
        uint256 n = curve.length;
        if (n == 0) revert ExitCurveEmpty();
        for (uint256 i; i < n; ++i) {
            if (marketValue <= curve[i].thresholdUsd18) return curve[i].recoveryBps;
        }
        return curve[n - 1].recoveryBps;
    }

    /// @notice §4.1–§4.5 — value one asset position.
    function valueAsset(Types.AssetRiskInput memory a) internal pure returns (Types.AssetValuation memory v) {
        v.assetId = a.assetId;

        // §4.1 market value
        v.marketValueUsd18 = mulDiv(a.quantity, a.priceUsd18, 10 ** a.decimals);

        // §4.2 haircut mark — fixed order, sequential, each step floors
        uint256 m = v.marketValueUsd18;
        Types.RiskParameters memory p = a.params;
        m = mulDiv(m, Types.BPS - p.haircutMarketBps, Types.BPS);
        m = mulDiv(m, Types.BPS - p.haircutLiquidityBps, Types.BPS);
        m = mulDiv(m, Types.BPS - p.haircutIssuerBps, Types.BPS);
        m = mulDiv(m, Types.BPS - p.haircutSettlementBps, Types.BPS);
        m = mulDiv(m, Types.BPS - p.haircutCrosschainBps, Types.BPS);
        v.haircutMarkUsd18 = m;

        // §4.3 stressed exit
        v.stressedExitUsd18 =
            mulDiv(v.marketValueUsd18, selectRecoveryBps(a.exitCurve, v.marketValueUsd18), Types.BPS);

        // §4.5 recognised = min(candidates)
        uint256 recognised =
            v.haircutMarkUsd18 < v.stressedExitUsd18 ? v.haircutMarkUsd18 : v.stressedExitUsd18;

        // §4.4 redemption floor participates only when redemption actually exists
        if (a.redemptionSupported) {
            v.redemptionFloorUsd18 = mulDiv(v.marketValueUsd18, a.redemptionFloorBps, Types.BPS);
            if (v.redemptionFloorUsd18 < recognised) recognised = v.redemptionFloorUsd18;
        }

        v.recognizedUsd18 = recognised;
    }

    /// @notice §5.1 — the restrictions implied by this asset's inputs at time `nowTs`.
    /// @dev A zero-quantity position contributes no gates. Holding nothing of a suspended asset
    ///      must not restrict an account, or every retired asset would freeze the protocol.
    /// @dev Ages are computed with saturating subtraction. A timestamp ahead of `nowTs` is not
    ///      exotic — ordinary L2 clock skew puts an oracle a second into the future routinely —
    ///      and unsigned subtraction panics on it, which reverted `evaluate()` entirely and took
    ///      reads, borrows and repayments down with it. The TypeScript and Python implementations
    ///      compute a signed difference and treat a future timestamp as age zero, so the panic
    ///      was also a three-way divergence the canonical fixtures could not see: they contain no
    ///      future-dated timestamp. Saturating here matches the other implementations, and a
    ///      future timestamp reads as maximally fresh rather than maximally stale.
    function _age(uint64 nowTs, uint64 then) private pure returns (uint64) {
        return nowTs > then ? nowTs - then : 0;
    }

    function assetGates(Types.AssetRiskInput memory a, uint64 nowTs) internal pure returns (uint32 g) {
        if (a.quantity == 0) return 0;

        if (_age(nowTs, a.priceUpdatedAt) > a.params.maxOracleAge) g |= Types.GATE_ORACLE_STALE;
        if (a.priceUsd18 == 0) g |= Types.GATE_ORACLE_INVALID;
        if (_age(nowTs, a.passportCommittedAt) > a.params.maxPassportAge) g |= Types.GATE_PASSPORT_STALE;
        if (a.passportStatus == Types.PassportStatus.CONFLICTED) g |= Types.GATE_CLAIM_CONFLICT;
        if (
            a.passportStatus == Types.PassportStatus.SUSPENDED || a.assetStatus == Types.AssetStatus.SUSPENDED
        ) g |= Types.GATE_ASSET_SUSPENDED;
    }

    // ---------------------------------------------------------------------------------
    // §4.6 + §5 Portfolio evaluation
    // ---------------------------------------------------------------------------------

    /// @notice The whole pipeline. This is the number the protocol lends against.
    /// @param assets Held positions, ascending by `assetId`. Ordering is asserted, not assumed:
    ///        truncated sums are order-dependent, so an unordered array would silently produce a
    ///        different total than the reference model.
    function evaluate(
        Types.AssetRiskInput[] memory assets,
        Types.AccountInput memory account,
        Types.SequencerInput memory seq,
        uint64 nowTs
    ) internal pure returns (Types.RiskResult memory r, Types.AssetValuation[] memory vals) {
        uint256 n = assets.length;
        vals = new Types.AssetValuation[](n);

        // Sequencer gates are portfolio-wide: an unarbitrable L2 price is not a price.
        if (!seq.up) {
            r.gates |= Types.GATE_SEQUENCER_DOWN;
        } else if (_age(nowTs, seq.lastRestartAt) < seq.gracePeriod) {
            r.gates |= Types.GATE_SEQUENCER_GRACE;
        }

        uint256 rawTotal;
        for (uint256 i; i < n; ++i) {
            if (i > 0 && uint256(assets[i].assetId) <= uint256(assets[i - 1].assetId)) {
                revert AssetsNotOrdered();
            }
            vals[i] = valueAsset(assets[i]);
            r.gates |= assetGates(assets[i], nowTs);
            rawTotal += vals[i].recognizedUsd18;
        }

        // §4.6 concentration — single pass against the uncapped total
        for (uint256 i; i < n; ++i) {
            uint256 cap = mulDiv(rawTotal, assets[i].params.maxConcentrationBps, Types.BPS);
            uint256 capped = vals[i].recognizedUsd18 < cap ? vals[i].recognizedUsd18 : cap;
            vals[i].cappedUsd18 = capped;

            r.totalRecognizedUsd18 += capped;
            r.borrowLimitUsd18 += mulDiv(capped, assets[i].params.initialLtvBps, Types.BPS);
            r.maintenanceLimitUsd18 += mulDiv(capped, assets[i].params.maintenanceLtvBps, Types.BPS);
            r.liquidationLimitUsd18 += mulDiv(capped, assets[i].params.liquidationLtvBps, Types.BPS);
        }

        // §3.1 debt reconstruction, rounds up
        r.debtUsd18 = mulDivUp(account.scaledPrincipal, account.borrowIndex, Types.WAD);

        // §5.1 status
        Types.AccountStatus base;
        if (r.debtUsd18 == 0 || r.debtUsd18 <= r.borrowLimitUsd18) {
            base = Types.AccountStatus.NORMAL;
        } else if (r.debtUsd18 <= r.maintenanceLimitUsd18) {
            base = Types.AccountStatus.NO_NEW_RISK;
        } else if (r.debtUsd18 <= r.liquidationLimitUsd18) {
            base = Types.AccountStatus.REDUCE_ONLY;
        } else {
            base = Types.AccountStatus.MARGIN_CALL;
        }

        Types.AccountStatus gateFloor =
            r.gates != 0 ? Types.AccountStatus.NO_NEW_RISK : Types.AccountStatus.NORMAL;

        r.status = max(max(base, gateFloor), account.statusOverride);

        // §5 capacity
        if (r.status == Types.AccountStatus.NORMAL) {
            uint256 used = r.debtUsd18 + account.reservedUsd18;
            r.availableBorrowUsd18 = r.borrowLimitUsd18 > used ? r.borrowLimitUsd18 - used : 0;
        }

        r.healthFactorWad =
            r.debtUsd18 == 0 ? type(uint256).max : mulDiv(r.maintenanceLimitUsd18, Types.WAD, r.debtUsd18);
    }

    // ---------------------------------------------------------------------------------
    // §6 Interest
    // ---------------------------------------------------------------------------------

    /// @notice Two-slope utilisation curve. Returns an annualised borrow rate in bps.
    function borrowRateBps(
        uint256 cash,
        uint256 borrows,
        uint16 baseBps,
        uint16 slope1Bps,
        uint16 slope2Bps,
        uint16 kinkBps
    ) internal pure returns (uint256) {
        if (borrows == 0) return baseBps;
        uint256 u = mulDiv(borrows, Types.BPS, cash + borrows);
        if (u <= kinkBps) {
            return baseBps + mulDiv(u, slope1Bps, kinkBps);
        }
        return baseBps + slope1Bps + mulDiv(u - kinkBps, slope2Bps, Types.BPS - kinkBps);
    }

    /// @notice Advance the borrow index. Monotone non-decreasing by construction.
    function accrueIndex(uint256 index, uint256 rateBps, uint256 dt) internal pure returns (uint256) {
        if (dt == 0 || rateBps == 0) return index;
        // Floored, so the index can never overstate what borrowers owe through rounding alone.
        return index + mulDiv(index, rateBps * dt, Types.BPS * Types.SECONDS_PER_YEAR);
    }
}

src/interfaces/ILiquidationRoute.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

/// @title ILiquidationRoute
/// @notice One way out of a position.
/// @dev Liquidation is a router, not a market sell. The canonical PRD §33 lists seven exits —
///      Exchange OS, OKX DEX, issuer redemption, RFQ market maker, securities return, offsetting
///      hedge, approved secondary venue — and they differ in the ways that decide which one is
///      right: how much they pay, how long they take, and how likely they are to fail halfway.
///
///      Only routes that exist are registered. An adapter for a venue Usance has no access to would
///      quote numbers nobody can honour, and a router that selected it would look like it was
///      working. `LiquidationManager` reports the routes it has and does not pretend about the rest.
interface ILiquidationRoute {
    /// @notice Identity, for receipts and for refusing to register the same route twice.
    function routeId() external view returns (bytes32);

    /// @notice Human-readable, e.g. "direct settlement (testnet)".
    function description() external view returns (string memory);

    /// @notice Whether this route can act right now. A route with no counterparty is not a route.
    function isAvailable(bytes32 assetId) external view returns (bool);

    /**
     * @notice What this route expects to recover for `amount` of `assetId`, in settlement tokens.
     *
     * @dev Every deduction is separate because they behave differently under stress and a single
     *      net number hides which one moved.
     *
     *      - `proceeds` is gross, at the route's own view of price.
     *      - `fees` is what the venue takes.
     *      - `latencyHaircut` prices the time between committing and settling. A route that pays
     *        more but settles in two days is not obviously better than one that pays less now.
     *      - `failureHaircut` prices the chance the route does not complete at all, which is the
     *        deduction a quoted mark price never contains and the reason route choice cannot be
     *        made on price alone.
     *
     *      `expectedRecovery = proceeds - fees - latencyHaircut - failureHaircut`, and it is the
     *      only number the router ranks on.
     */
    function quote(bytes32 assetId, uint256 amount)
        external
        view
        returns (
            uint256 proceeds,
            uint256 fees,
            uint256 latencyHaircut,
            uint256 failureHaircut,
            uint256 expectedRecovery
        );

    /**
     * @notice Sell `amount` of `assetId`, returning settlement tokens to `recipient`.
     * @dev The route is handed the collateral before this is called. It must return at least
     *      `minProceeds` or revert: a route that silently under-delivers turns a liquidation that
     *      should have been abandoned into a realised loss.
     */
    function execute(bytes32 assetId, uint256 amount, uint256 minProceeds, address recipient)
        external
        returns (uint256 proceeds);
}

